import{c as a,Q as e,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"ShiftRight（右移位数为Tensor）","description":"","frontmatter":{},"headers":[{"level":1,"title":"ShiftRight（右移位数为Tensor）","slug":"shiftright右移位数为tensor"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/逻辑计算/ShiftRight（右移位数为Tensor）.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/逻辑计算/ShiftRight（右移位数为Tensor）.md"}'),i={name:"api/SIMD-API/基础API/Memory矢量计算/逻辑计算/ShiftRight（右移位数为Tensor）.md"};function l(d,t,r,o,h,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="shiftright-右移位数为tensor" tabindex="-1">ShiftRight（右移位数为Tensor） <a class="header-anchor" href="#shiftright-右移位数为tensor" aria-label="Permalink to &quot;ShiftRight（右移位数为Tensor）&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>源操作数内每个元素做右移。</p><p>对无符号数据类型的源操作数做逻辑右移，对有符号数据类型的源操作数做算术右移。</p><p>逻辑右移为去掉最低位，最高位填充为0。</p><p>算术右移为去掉最低位，最高位复制符号位。</p><p>例：数据类型uint16_t，二进制数 1010101010101010，逻辑右移一位结果为 0101010101010101；</p><p>数据类型int16_t，二进制数 1010101010101010，算术右移一位结果为 1101010101010101；</p><p>数据类型int16_t，二进制数 1010101010101010，算术右移三位结果为 1111010101010101。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T, typename U&gt;</span></span>
<span class="line"><span>__aicore__ inline void ShiftRight(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;U&gt;&amp; src1, const int32_t&amp; count)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>源/目的操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、uint8_t、int16_t、uint16_t、int32_t、uint32_t、int64_t、uint64_t。</td></tr><tr><td>U</td><td>源操作数数据类型。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、int16_t、int32_t、int64_t。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。</td></tr><tr><td>src0</td><td>输入</td><td>源操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 数据类型需要与目的操作数保持一致。</td></tr><tr><td>src1</td><td>输入</td><td>存放右移位数的LocalTensor，数据类型的字节数需要与源src0操作数Tensor中的元素数据类型的字节数相匹配，不支持设置为负数。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>对于逻辑位移（无符号数据类型），如果位移量大于数据类型位宽，则输出为0。</p></li><li><p>对于算数位移（有符号数据类型），如果src0小于0，src1大于0，并且位移量大于数据类型位宽，则输出-1；如果src0大于0，并且位移量大于数据类型位宽，则输出0。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::ShiftRight(dstLocal, srcLocal0, srcLocal1, 512);</span></span></code></pre></div><p>结果示例如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>输入数据(srcLocal0): [1 2 3 ... 512]</span></span>
<span class="line"><span>输入数据(srcLocal1): [2 2 2 ... 2]</span></span>
<span class="line"><span>输出数据(dstLocal): [0 0 0 1 1 1 1 ... 128]</span></span></code></pre></div>`,26)])])}const g=a(i,[["render",l]]);export{u as __pageData,g as default};
